sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {

    console.log("Visualisation component filter cs");

    var assignmentGroup = api.data.Group_Manager.results[0].sys_id.value;

    console.log(assignmentGroup, "assignmentGroup");

    // apply filter to visualisation components!!! What a nice way!!

    const mergePARFiltersV2 = imports["global.mergePARFilters"]().v2;

    api.setState("parFilters", ({
        currentValue,
        api
    }) => {

        const customFilter = [
            {
                type: "query",
                apply_to: ["incident"], //Access page property value
                encoded_query: "assignment_group=" + assignmentGroup
            },
        ];

        const {
            parFilters,
            encodedQueries
        } = mergePARFiltersV2(
            currentValue,
            customFilter
        );

        api.setState("encodedQueries", encodedQueries);
        console.log(parFilters);

        return parFilters;

    });

}
